type LegacyFixedTemplateRecord = Record<string, unknown>;
type LoadedFixedTemplate = {
  raw: LegacyFixedTemplateRecord;
  template: FixedExpenseDoc;
};

type LegacyRecord = Record<string, unknown>;
type LoadedRecord = {
  raw: LegacyRecord;
  entry: EntryDoc;
};
type QueryDoc = { id: string; data: () => unknown };
type QuerySnapshot = { docs: QueryDoc[] };
type MonthEntriesCacheValue = EntryDoc[];
type ListMonthEntriesOptions = {
  ensureFixedRealizations?: boolean;
};

let attemptedLegacyTemplateFallback = false;
let attemptedLegacyRecordFallback = false;
let cachedRecordsKey = "";
let cachedRecords: LoadedRecord[] | null = null;
let cachedRecordsPromise: Promise<LoadedRecord[]> | null = null;
let cachedMonthEntriesKey = "";
