const recordsStateListeners = new Set<() => void>();

function recordsCacheKey(context: SessionContext): string {
  return `${context.uid}:${context.householdId}:${context.email}`;
}

function clearRecordsCache(): void {
  cachedRecordsKey = "";
  cachedRecords = null;
  cachedRecordsPromise = null;
  cachedMonthEntriesKey = "";
  cachedMonthEntries = new Map();
  cachedMonthEntriesPromises = new Map();
  cachedScopedMonthEntriesKey = "";
  cachedScopedMonthEntries = new Map();
  cachedScopedMonthEntriesPromises = new Map();
  cachedAvailableMonthKeysKey = "";
  cachedAvailableMonthKeys = null;
  cachedAvailableMonthKeysPromise = null;
}

function fixedTemplatesCacheKey(context: SessionContext): string {
  return `${context.uid}:${context.householdId}:${context.email}`;
}

function clearFixedTemplatesCache(): void {
  cachedFixedTemplatesKey = "";
  cachedFixedTemplates = null;
  cachedFixedTemplatesPromise = null;
}

export function subscribeRecordsState(listener: () => void): () => void {
  recordsStateListeners.add(listener);
  return () => {
    recordsStateListeners.delete(listener);
  };
}

export function invalidateRecordsState(): void {
  clearRecordsCache();
  clearFixedTemplatesCache();
  recordsStateListeners.forEach((listener) => listener());
}

